    }),
  });
  const url = await startHistoryEngine(new MongoSessionStore({collection: brokenCollection}));
  const {socket, connected} = await openSocket(url, 'token-u1');
  await completeTurnOnSocket(socket, 'private-symptom-note');
  capturedErrors.length = 0;

  const check = await askWithPongFence(socket, {type: 'list_conversations'});
  const clientMessage = check.reply.message ?? '';
  const serializedLogs = JSON.stringify(capturedErrors);

  return {
    code: check.reply.code,
    frameTypes: check.frameTypes,
    socketStayedOpen: socket.readyState === WebSocket.OPEN,
    containsStoreDetail: mentionsDetail(clientMessage),
    loggedSessionMatch: capturedErrors.some(entry => entry.sessionId === connected.sessionId),
