}

async function resumeConversation(url: string, token: string, sessionId: string) {
  const socket = connectClient(`${url}?sessionId=${sessionId}`, token);
  return new Promise<{resumed: boolean | undefined; firstUserPrompt: string | undefined}>(resolve => {
    let resumedFlag: boolean | undefined;
    socket.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type === 'connected') {
        resumedFlag = frame.resumed;
        if (!frame.resumed) resolve({resumed: frame.resumed, firstUserPrompt: undefined});
        return;
      }
      if (frame.type === 'entry_upsert' && frame.entry?.role === 'user') {
        resolve({resumed: resumedFlag, firstUserPrompt: frame.entry.content});
      }
    });
  });
}

async function listDuringStream(socket: WebSocket, gate: {release: () => void}) {
  const seenFrames: WireFrame[] = [];
  let notifyFirst = (): void => undefined;
  const firstArrived = new Promise<void>(resolve => {
    notifyFirst = resolve;
  });
  const doneStreaming = new Promise<void>(resolve => {
    socket.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      seenFrames.push(frame);
      if (seenFrames.length === 1) notifyFirst();
      if (frame.type === 'stream_end') resolve();
    });
  });

  socket.send(JSON.stringify({type: 'list_conversations'}));
  await Promise.race([firstArrived, pauseTick(50)]);
  gate.release();
  await doneStreaming;

  return {
    firstReply: seenFrames[0],
    typesAfterDelta: seenFrames.map(frame => frame.type),
  };
}

async function askManyFrames(socket: WebSocket, payloads: Array<Record<string, unknown>>): Promise<WireFrame[]> {
  const replies: WireFrame[] = [];
  for (const payload of payloads) {
    replies.push(await askNextFrame(socket, payload));
  }
  return replies;
}

async function askWithPongFence(socket: WebSocket, payload: Record<string, unknown>) {
  const reply = await askNextFrame(socket, payload);
  const trailing: string[] = [reply.type];
  const untilPong = new Promise<string[]>(resolve => {
    const onMessage = (raw: WebSocket.RawData): void => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      trailing.push(frame.type);
      if (frame.type === 'pong') {
        socket.off('message', onMessage);
        resolve(trailing);
      }
    };
    socket.on('message', onMessage);
  });
  socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
  return {reply, frameTypes: await untilPong};
}

async function completeTurnOnSocket(socket: WebSocket, prompt: string): Promise<void> {
  const finished = framesUntil(socket, 'stream_end');
  socket.send(JSON.stringify({type: 'user_message', content: prompt}));
  await finished;
}

async function openSocket(url: string, token: string): Promise<{socket: WebSocket; connected: WireFrame}> {
  const socket = connectClient(url, token);
  const connected = await nextFrame(socket);
  return {socket, connected};
}

async function askNextFrame(socket: WebSocket, payload: Record<string, unknown>): Promise<WireFrame> {
  const pending = nextFrame(socket);
  socket.send(JSON.stringify(payload));
  return pending;
}

function nextFrame(socket: WebSocket): Promise<WireFrame> {
  return new Promise<WireFrame>(resolve => {
    const onMessage = (raw: WebSocket.RawData): void => {
      socket.off('message', onMessage);
      resolve(JSON.parse(String(raw)) as WireFrame);
    };
    socket.on('message', onMessage);
  });
}

function startHistoryEngine(session: SessionStore): Promise<string> {
  const transport = {port: 0, resume: {enabled: true}, history: {enabled: true}};
  return startEngineUrl(session, transport);
}

function startDefaultEngine(session: SessionStore): Promise<string> {
  const transport = {port: 0, resume: {enabled: true}};
  return startEngineUrl(session, transport);
}

async function startEngineUrl(
  session: SessionStore,
