    clear: () => inner.clear(),
    latestFor: userId => inner.latestFor(userId),
    listFor: (userId: string | number, options?: SessionListOptions) => {
      calls.push({userId, limit: options?.limit, before: options?.before});
      return inner.listFor(userId, options);
    },
  };
  return {store, calls};
}

function fiveMemberStore(): SessionStore {
  const sessions = new Map<string, ChatSession>();
  return {
    create: (sessionId, userId) => {
      const created: ChatSession = {sessionId, userId, entries: []};
      sessions.set(sessionId, created);
      return created;
    },
    get: sessionId => sessions.get(sessionId),
    delete: sessionId => sessions.delete(sessionId),
    count: () => sessions.size,
    clear: () => sessions.clear(),
  };
}

function gatedProvider(): {provider: AIProvider; gate: {until: Promise<void>; release: () => void}} {
  const gate = deferred();
  const provider: AIProvider = {
    async *sendMessage() {
      yield {type: 'text', text: 'Hal'};
      await gate.until;
      yield {type: 'text', text: 'lo'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  return {provider, gate};
}

function headCursorFrom(summaries: WireSummary[]): {updatedAt: string; sessionId: string} {
  const head = summaries[0];
  if (head === undefined) return {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'placeholder'};
  return {updatedAt: head.updatedAt, sessionId: head.sessionId};
}

function isIsoSummary(summary: WireSummary): boolean {
  const hasExpectedKeys = JSON.stringify(Object.keys(summary).sort()) === JSON.stringify(EXPECTED_SUMMARY_KEYS);
  if (!hasExpectedKeys) return false;
  return ISO_STAMP.test(summary.createdAt) && ISO_STAMP.test(summary.updatedAt);
}

function mentionsDetail(message: string): boolean {
  return message.includes('db-host.internal') || message.includes('primary stepped down');
}

function pauseTick(ms = 5): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}
